def resolve_document_fico(facts: Dict[str, Any]) -> Optional[int]:
    primary = get_fact(facts, "primary_fico_score", "credit_score_mention")
    if primary is not None:
        try:
            score = int(float(primary))
            if 300 <= score <= 850:
                return score
        except (TypeError, ValueError):
            pass
    bureau = facts.get("bureau_fico_scores")
    if isinstance(bureau, dict) and bureau:
        scores = sorted(int(v) for v in bureau.values() if isinstance(v, (int, float)) and 300 <= v <= 850)
        if scores:
            return scores[len(scores) // 2]
    return None


def resolve_appraisal_noi(facts: Dict[str, Any]) -> Optional[float]:
    return _safe_float(get_fact(facts, "noi", "net_operating_income"))


def resolve_noi_from_operations(facts: Dict[str, Any]) -> Optional[float]:
    noi = _safe_float(get_fact(facts, "noi", "net_operating_income"))
    if noi is not None:
        return noi
    egi = _safe_float(get_fact(facts, "effective_gross_income"))
    gpr = _safe_float(get_fact(facts, "gross_potential_rent", "gpr", "gross_rent"))
    vacancy = _safe_float(get_fact(facts, "vacancy", "vacancy_loss"))
    opex = _safe_float(get_fact(facts, "operating_expenses", "total_expenses", "opex"))
    base = egi if egi is not None else gpr
    if base is None:
        return None
    effective = base
    if vacancy is not None:
        effective = base - vacancy
    if opex is None:
        return None
    return effective - opex


def compute_noi(facts: Dict[str, Any]) -> Optional[float]:
    return resolve_noi_from_operations(facts)


def resolve_t12_noi(facts: Dict[str, Any]) -> Optional[float]:
    """NOI from T12-specific keys when document_type was t12."""
    if str(facts.get("document_type", "")) == "t12_operating_statement":
        return resolve_noi_from_operations(facts)
    return _safe_float(get_fact(facts, "t12_noi"))


def resolve_economic_occupancy(facts: Dict[str, Any]) -> Optional[float]:
    v = _safe_float(get_fact(facts, "economic_occupancy"))
    if v is not None:
        return v / 100.0 if v > 1 else v
    if facts.get("pre_leased"):
        return 1.0
    return resolve_occupancy(facts)


def resolve_wale_years(facts: Dict[str, Any]) -> Optional[float]:
    return _safe_float(get_fact(facts, "wale_years", "wale", "weighted_average_lease_term"))

